import { useEffect, useMemo, useState } from 'react';
import styles from './Ludo.module.css';

const GRID = 9;
export const TRACK_LEN = 32; // perimeter of a 9x9 grid: 9 + 8 + 8 + 7
export const HOME_LEN = 4;
export const FINISHED = TRACK_LEN + HOME_LEN;
const PLAYER2_START = 16; // opposite side of the ring from player1's start (0)

// The ring is generated by walking the border of a 9x9 grid rather than a
// hand-typed coordinate list — a classic cross-shaped Ludo board needs a lot
// of fiddly per-cell coordinates that are easy to get subtly wrong and hard
// to verify without eyes on a running browser, so this trades traditional
// board art for a layout that's mechanically guaranteed to be a closed loop.
function buildRing() {
  const cells = [];
  for (let c = 0; c < GRID; c++) cells.push({ row: 0, col: c });
  for (let r = 1; r < GRID; r++) cells.push({ row: r, col: GRID - 1 });
  for (let c = GRID - 2; c >= 0; c--) cells.push({ row: GRID - 1, col: c });
  for (let r = GRID - 2; r >= 1; r--) cells.push({ row: r, col: 0 });
  return cells;
}
export const RING = buildRing();
export const SAFE_CELLS = new Set([0, PLAYER2_START]);

// Engine-only — just where each side starts on the ring. Display labels
// and colors are a separate, local concern (see LOCAL_META below) since
// the online version needs real member names instead of "You"/"Computer".
export const SIDE_START = { player1: 0, player2: PLAYER2_START };

const LOCAL_META = {
  player1: { label: 'You', color: 'var(--accent)' },
  player2: { label: 'Computer', color: 'var(--danger)' },
};

export function freshTokens() { return [-1, -1, -1, -1]; }

export function absoluteCell(side, relPos) {
  if (relPos < 0 || relPos >= TRACK_LEN) return null;
  return (SIDE_START[side] + relPos) % TRACK_LEN;
}

export function tokenLabel(pos) {
  if (pos === -1) return 'Base';
  if (pos >= FINISHED) return 'Finished';
  if (pos >= TRACK_LEN) return `Home stretch ${pos - TRACK_LEN + 1}/${HOME_LEN}`;
  return `Step ${pos + 1}/${TRACK_LEN}`;
}

/** Legal token indices for `side` given a dice roll. */
export function legalMoves(tokens, roll) {
  return tokens
    .map((pos, i) => ({ i, pos }))
    .filter(({ pos }) => {
      if (pos >= FINISHED) return false;
      if (pos === -1) return roll === 6;
      return pos + roll <= FINISHED;
    })
    .map(({ i }) => i);
}

export function applyMove(state, side, tokenIndex, roll) {
  const next = { player1: [...state.player1], player2: [...state.player2] };
  const pos = next[side][tokenIndex];
  const newPos = pos === -1 ? 0 : pos + roll;
  next[side][tokenIndex] = newPos;

  if (newPos < TRACK_LEN) {
    const landedCell = absoluteCell(side, newPos);
    if (!SAFE_CELLS.has(landedCell)) {
      const otherSide = side === 'player1' ? 'player2' : 'player1';
      next[otherSide] = next[otherSide].map((oppPos) => (
        oppPos >= 0 && oppPos < TRACK_LEN && absoluteCell(otherSide, oppPos) === landedCell ? -1 : oppPos
      ));
    }
  }
  return next;
}

/** Heuristic AI for the vs-computer mode only — always plays player2. */
function pickComputerMove(tokens, opponentTokens, roll, moves) {
  // 1) a move that captures the opponent
  for (const i of moves) {
    const pos = tokens[i];
    const newPos = pos === -1 ? 0 : pos + roll;
    if (newPos < TRACK_LEN) {
      const cell = absoluteCell('player2', newPos);
      if (!SAFE_CELLS.has(cell) && opponentTokens.some((p) => p >= 0 && p < TRACK_LEN && absoluteCell('player1', p) === cell)) return i;
    }
  }
  // 2) bring a new token out on a 6
  const fromBase = moves.find((i) => tokens[i] === -1);
  if (roll === 6 && fromBase !== undefined) return fromBase;
  // 3) push the most-advanced token forward
  return moves.reduce((best, i) => (tokens[i] > tokens[best] ? i : best), moves[0]);
}

/** Simplified 2-player Ludo, you vs the computer — real rules (roll to
 *  leave base on a 6, capture opponents off safe cells, land exactly on
 *  the final slot to finish, an extra roll on a 6, three 6s in a row
 *  forfeits the extra turn) on a procedurally generated ring board rather
 *  than a traditional hand-drawn cross board. First to get all 4 tokens
 *  home wins. (OnlineLudo.jsx plays the same engine against another
 *  member instead of this component's AI.) */
export function Ludo() {
  const [tokens, setTokens] = useState({ player1: freshTokens(), player2: freshTokens() });
  const [turn, setTurn] = useState('player1');
  const [roll, setRoll] = useState(null);
  const [moves, setMoves] = useState([]);
  const [sixStreak, setSixStreak] = useState(0);
  const [message, setMessage] = useState('Your turn — roll the dice.');

  const winner = tokens.player1.every((p) => p >= FINISHED) ? 'player1'
    : tokens.player2.every((p) => p >= FINISHED) ? 'player2' : null;

  function reset() {
    setTokens({ player1: freshTokens(), player2: freshTokens() });
    setTurn('player1');
    setRoll(null);
    setMoves([]);
    setSixStreak(0);
    setMessage('Your turn — roll the dice.');
  }

  function endTurnOrReroll(rolledSix) {
    if (rolledSix && sixStreak + 1 < 3) {
      setSixStreak((s) => s + 1);
      setRoll(null);
      setMoves([]);
      setMessage(turn === 'player1' ? 'Six! Roll again.' : 'Computer rolled a six and goes again…');
    } else {
      const next = turn === 'player1' ? 'player2' : 'player1';
      setSixStreak(0);
      setTurn(next);
      setRoll(null);
      setMoves([]);
      setMessage(next === 'player1' ? 'Your turn — roll the dice.' : 'Computer is rolling…');
    }
  }

  function doRoll() {
    if (winner || roll !== null) return;
    const r = 1 + Math.floor(Math.random() * 6);
    const side = turn;
    const legal = legalMoves(tokens[side], r);
    setRoll(r);
    setMoves(legal);
    if (legal.length === 0) {
      setMessage(`${LOCAL_META[side].label} rolled a ${r} — no valid move.`);
      setTimeout(() => endTurnOrReroll(r === 6), 700);
    } else if (side === 'player2') {
      setMessage(`Computer rolled a ${r}…`);
      setTimeout(() => {
        const choice = pickComputerMove(tokens.player2, tokens.player1, r, legal);
        setTokens((t) => applyMove(t, 'player2', choice, r));
        setTimeout(() => endTurnOrReroll(r === 6), 300);
      }, 500);
    } else {
      setMessage(`You rolled a ${r} — move a highlighted token.`);
    }
  }

  function playerMoveToken(i) {
    if (turn !== 'player1' || roll === null || !moves.includes(i)) return;
    setTokens((t) => applyMove(t, 'player1', i, roll));
    endTurnOrReroll(roll === 6);
  }

  useEffect(() => {
    if (turn === 'player2' && roll === null && !winner) {
      const t = setTimeout(doRoll, 550);
      return () => clearTimeout(t);
    }
    return undefined;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [turn, roll, winner]);

  const cellOccupants = useMemo(() => {
    const map = new Map();
    for (const side of ['player1', 'player2']) {
      tokens[side].forEach((pos, i) => {
        if (pos >= 0 && pos < TRACK_LEN) {
          const cell = absoluteCell(side, pos);
          if (!map.has(cell)) map.set(cell, []);
          map.get(cell).push({ side, i });
        }
      });
    }
    return map;
  }, [tokens]);

  return (
    <div className={styles.wrap}>
      <p className={styles.status}>
        {winner ? `${LOCAL_META[winner].label} won!` : message}
      </p>

      <div className={styles.board} style={{ '--n': GRID }}>
        {RING.map((cell, i) => {
          const occupants = cellOccupants.get(i) || [];
          return (
            <div
              key={i}
              className={`${styles.ringCell} ${SAFE_CELLS.has(i) ? styles.safeCell : ''}`}
              style={{ gridRow: cell.row + 1, gridColumn: cell.col + 1 }}
            >
              {occupants.map((o) => (
                <span
                  key={`${o.side}-${o.i}`}
                  className={styles.token}
                  style={{ background: LOCAL_META[o.side].color }}
                  title={`${LOCAL_META[o.side].label} token ${o.i + 1}`}
                />
              ))}
            </div>
          );
        })}
      </div>

      <div className={styles.controls}>
        <button type="button" className="btn btn-primary" onClick={doRoll} disabled={Boolean(winner) || turn !== 'player1' || roll !== null}>
          {roll === null ? 'Roll dice' : `Rolled ${roll}`}
        </button>
      </div>

      <div className={styles.sides}>
        {['player1', 'player2'].map((side) => (
          <div key={side} className={styles.sidePanel}>
            <div className={styles.sideHead} style={{ color: LOCAL_META[side].color }}>
              {LOCAL_META[side].label}{turn === side && !winner ? ' · turn' : ''}
            </div>
            <div className={styles.tokenList}>
              {tokens[side].map((pos, i) => {
                const canMove = side === 'player1' && turn === 'player1' && moves.includes(i);
                return (
                  <button
                    key={i}
                    type="button"
                    className={`${styles.tokenRow} ${canMove ? styles.movable : ''}`}
                    onClick={() => playerMoveToken(i)}
                    disabled={!canMove}
                  >
                    <span className={styles.tokenDot} style={{ background: LOCAL_META[side].color }} />
                    {tokenLabel(pos)}
                  </button>
                );
              })}
            </div>
          </div>
        ))}
      </div>

      <button type="button" className="btn" onClick={reset}>New game</button>
    </div>
  );
}
